1	import { readFileSync } from 'node:fs';
2	import { fileURLToPath } from 'node:url';
3	import { compileSchemaValidator } from './validator.js';
4	
5	export { workspaceJsonSchema } from './schema.js';
6	export { validateStoredKey } from './path-identity.js';
7	export type { StoredKeyResult, StoredKeyRejection } from './path-identity.js';
8	export { inspectStoredKeys } from './stored-key-inspection.js';
9	export type {
10	  StoredKeyDocument,
11	  StoredKeySurface,
12	  StoredKeyFinding,
13	} from './stored-key-inspection.js';
14	export type {
15	  WorkspaceJson,
16	  WorkspacePackage,
17	  WorkspaceConvention,
18	  WorkspaceAgentFiles,
19	  WorkspaceGitSummary,
20	  WorkspaceHygiene,
21	  WorkspaceJsonV3,
22	  FrameworkEntry,
23	  FileIndexEntry,
24	  IntelligenceState,
25	  CoChangeEntry,
26	  CoChangeEntryCommon,
27	  LegacyCoChangeEntry,
28	  ObservationCoChangeEntry,
29	  FragilityEntry,
30	  WorkspaceJsonV4,
31	} from './types.js';
32	
33	import type { WorkspaceJsonV3, WorkspaceJsonV4 } from './types.js';
34	
35	type WorkspaceJsonDocument = WorkspaceJsonV3 | WorkspaceJsonV4;
36	
37	// The runtime validator consumes the schema artifact that is published with
38	// the package, rather than the authoring-time TypeScript mirror.
39	const packagedSchema = JSON.parse(
40	  readFileSync(fileURLToPath(new URL('../schema/v1.json', import.meta.url)), 'utf8'),
41	) as object;
42	const validateSchema = compileSchemaValidator<WorkspaceJsonDocument>(packagedSchema);
43	
44	/**
45	 * The package version, read from the packaged manifest rather than duplicated
46	 * here.
47	 *
48	 * It used to be a hardcoded literal, with a unit test asserting the literal.
49	 * That pair passes only while someone remembers to edit both during a release —
50	 * and Changesets rewrites `package.json` and `CHANGELOG.md`, never a constant in
51	 * source. The first release to move the number would have shipped a package
52	 * reporting the previous version, or gone red on a test asserting a string
53	 * nobody updated. Deriving it removes the second source of truth; the test now
54	 * asserts parity with the manifest instead of a literal.
55	 *
56	 * `package.json` is always present in an npm tarball, so this resolves in a
57	 * consumer's `node_modules` exactly as it does here.
58	 */
59	const packagedManifest = JSON.parse(
60	  readFileSync(fileURLToPath(new URL('../package.json', import.meta.url)), 'utf8'),
61	) as { version: string };
62	
63	export const version: string = packagedManifest.version;
64	
65	/**
66	 * The one co-change counting invariant JSON Schema cannot express.
67	 *
68	 * `support` counts the qualifying commits in which BOTH files changed;
69	 * `occurrences` counts those in which AT LEAST ONE did. The first set is a
70	 * subset of the second, so `support > occurrences` is not a debatable value —
71	 * it is arithmetically impossible, and it marks a producer that counted file
72	 * events, ordered relationships or two different analysis boundaries.
73	 *
74	 * Draft 2020-12 has no way to compare two instance values, so this lives beside
75	 * the schema rather than inside it. It is declared as an out-of-schema producer
76	 * obligation in ADR-003 amendment A-009, because an implementer validating with
77	 * a bare JSON Schema validator will not catch it and must be told so.
78	 *
79	 * OBSERVATION-FORM ONLY. A legacy entry has no `support`, and its `occurrences`
80	 * carries the pre-amendment meaning — never specified, not necessarily a union,
81	 * and therefore not something this invariant can be applied to. Skipping those
82	 * entries is what keeps this release a widening: no artifact that validated
83	 * before now fails here.
84	 *
85	 * Shape is not re-checked: this runs only after the schema has accepted the
86	 * document, so both fields are known to be integers when an entry is
87	 * well-formed. Anything that is not an entry-shaped object is left alone.
88	 */
89	function coChangeCountsAreCoherent(data: unknown): boolean {
90	  const generated = (data as { generated?: { coChange?: unknown } })?.generated;
91	  const entries = generated?.coChange;
92	  if (!Array.isArray(entries)) return true;
93	  return entries.every((entry) => {
94	    const { support, occurrences } = (entry ?? {}) as { support?: unknown; occurrences?: unknown };
95	    if (typeof support !== 'number' || typeof occurrences !== 'number') return true;
96	    return support <= occurrences;
97	  });
98	}
99	
100	export function validate(data: unknown): data is WorkspaceJsonV3 | WorkspaceJsonV4 {
101	  return validateSchema(data) && coChangeCountsAreCoherent(data);
102	}
103	
104	export function validateV4(data: unknown): data is WorkspaceJsonV4 {
105	  if (!validate(data)) return false;
106	  const g = (data as WorkspaceJsonV4).generated;
107	  return g.specVersion === '0.4';
108	}
109	
110	export function validateLegacy(data: unknown): boolean {
111	  if (typeof data !== 'object' || data === null) return false;
112	  const d = data as Record<string, unknown>;
113	  if (typeof d['version'] !== 'string') return false;
114	
115	  // A root `version` no longer identifies the pre-v0.3 shape on its own: ADR-004
116	  // makes it a legal optional mirror on v0.3/v0.4 documents. The distinguishing
117	  // property is the absence of `generated.specVersion`.
